#!/usr/bin/env python3

# This script requires `benchmark_times.csv`, generated by `create_csv.sh`
# This script generates one files: {benchmark}_{tool}_performances.png

import argparse
import numpy as np
import os
import pandas as pd
import re

parser = argparse.ArgumentParser(description="Plots the individual jobs for a specific benchmark+tool combination.")
parser.add_argument('--benchmark', '-b', type=str, action='store', required=True, help="Name of the benchmark to plot.")
parser.add_argument('--tool', '-t', type=str, action='store', required=True, help="Name of the tool to plot.")

args = parser.parse_args()

if not os.path.isfile('benchmark_times.csv'):
    print("Missing required input file benchmark_times.csv. Please run create_csv.sh first.")
    exit(1)

df = pd.read_csv('benchmark_times.csv')

df = df[(df['benchmark'] == args.benchmark) & (df['tool'] == args.tool)]

# Classify as cold/warm runs
df['cache'] = df['iteration'].apply(lambda x: 'cold' if x == 1 else 'warm')

# Now, summarize cold/warm timings with avg & stdev
df_grouped = df.groupby(['nnodes', 'cache', 'jobid'])['seconds'].agg(['mean', 'std'])
df_grouped = df_grouped.reset_index()
df_grouped = df_grouped[df_grouped['cache'] == 'warm']

print(df_grouped)
